cells.source:
uniform float speed : 0.0 .. 5.0 = 1.0;
uniform vec3 colorStart : color = vec3(0.5, 0.5, 0.5);
uniform vec3 colorEnd : color = vec3(0.7, 0.2, 0.9);
state float phase;
state int ledCount;
void update() {
  phase = phase + dt * speed;
}
vec3 shade(Led led) {
  float angle = (led.s - 0.5) * 6.2832;
  vec3 color = mix(colorStart, colorEnd, step(0.5 - abs(angle), phase));
  return color;
}

fill.shadeBody:
float angle = (led.s - 0.5) * 6.2832;
vec3 color = mix(colorStart, colorEnd, step(0.5 - abs(angle), phase));
return color;

