uniform float speed : 0.0 .. 5.0 = 1.0;
uniform vec3 color = vec3(1.0, 0.0, 0.0);
void update() {}
vec3 shade(Led led) {
  return color;
}

uniform float speed : 0.0 .. 5.0 = 1.0;
uniform vec3 color_start : color = vec3(0.2, 0.7, 0.8);
uniform vec3 color_end : color = vec3(0.9, 0.6, 0.4);
state float phase;
void update() {
  phase = phase + dt * speed;
}
vec3 shade(Led led) {
  float v = mix(length(phase - led.s * 6.2832), 1.0, clamp(led.dist - 0.5, 0.0, 1.0));
  vec3 start = color_start * v;
  vec3 end = color_end * (1.0 - v);
  return mix(start, end, step(0.5, led.dist) + mod(length(phase - led.s * 6.2832), 0.5) * clamp(mod(led.uv.x * 4.0 + led.uv.y * 7.0, 1.0), 0.5, 1.0));
}

