return mix(start, end, step(0.5, led.dist) + mod(length(phase - led.s * 6.2832), 0.5) * clamp(mod(led.uv.x * 4.0 + led.uv.y * 7.0, 1.0), 0.5, 1.0));

cells.source:
uniform float speed : 0.0 .. 10.0 = 5.0;
uniform vec3 color : color = 1.0, 1.0, 1.0;
state float phase;
void update() {
  phase = phase + dt * speed;
}
vec3 shade(Led led) {
  float v = sin(phase + led.s * 6.2832) + 0.5;
  vec3 hsv = vec3(v, 1.0, 1.0);
  return mix(color, hsv, smoothstep(0.0, 0.1, clamp((led.dist - 0.4) / (0.6 - 0.4), 0.0, 1.0)));
}

